mapper.select:
SELECT material_hash
  FROM readiness_evidence
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND environment = #{environment}
   AND identity_hash = #{identityHash}

SELECT evidence_id, format_version, requirement_code, status, origin, subject, version_ref,
       evidence_hash, evidence_reference, production_gate_evidence, reason_code, observed_at,
       expires_at, identity_hash, material_hash
  FROM readiness_evidence
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND environment = #{environment}
   AND requirement_code = #{requirementCode}
 ORDER BY evidence_id ASC
